 		field.SetBool(useICMP)
 	}
 	if field := value.FieldByName("PingMode"); field.IsValid() && field.CanSet() {
 		if useICMP {
 			field.SetInt(speedtestPingModeICMP)
 		} else {
 			field.SetInt(speedtestPingModeHTTP)
 		}
 	}
